import os
from typing import Any, Dict, Iterable, List, Optional, Union

from google.cloud import pubsub_v1


MessageInput = Dict[str, Any]


def publish_batch(
    project_id: str,
    topic_id: str,
    messages: Iterable[MessageInput],
    ordering_key: Optional[str] = None,
) -> List[str]:
    publisher = pubsub_v1.PublisherClient()
    topic_path = publisher.topic_path(project_id, topic_id)

    publish_futures = []

    for message in messages:
        data = message.get("data", b"")
        if isinstance(data, str):
            data = data.encode("utf-8")
        elif not isinstance(data, (bytes, bytearray)):
            data = str(data).encode("utf-8")

        attributes = {
            str(k): str(v)
            for k, v in (message.get("attributes") or {}).items()
        }

        if "id" in message and message["id"] is not None:
            attributes["message_id"] = str(message["id"])

        kwargs: Dict[str, Union[bytes, str]] = dict(attributes)
        if ordering_key is not None:
            kwargs["ordering_key"] = ordering_key
        elif message.get("ordering_key") is not None:
            kwargs["ordering_key"] = str(message["ordering_key"])

        future = publisher.publish(topic_path, bytes(data), **kwargs)
        publish_futures.append(future)

    return [future.result() for future in publish_futures]


def publish_batch_from_env(
    topic_id: str,
    messages: Iterable[MessageInput],
    project_id: Optional[str] = None,
    ordering_key: Optional[str] = None,
) -> List[str]:
    resolved_project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCP_PROJECT")
    if not resolved_project_id:
        raise ValueError("project_id is required or set GOOGLE_CLOUD_PROJECT/GCP_PROJECT")
    return publish_batch(
        project_id=resolved_project_id,
        topic_id=topic_id,
        messages=messages,
        ordering_key=ordering_key,
    )
